import UIKit

@MainActor enum MediaReviewFixtures {
    static func make() throws -> [MediaTile] {
        let root = FileManager.default.temporaryDirectory.appending(path: "xunju-media-review-" + UUID().uuidString, directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let colors: [UIColor] = [.init(red: 0.87, green: 0.91, blue: 1, alpha: 1), .init(red: 0.94, green: 0.88, blue: 0.82, alpha: 1), .init(red: 0.84, green: 0.94, blue: 0.88, alpha: 1)]
        var values: [MediaTile] = []
        for index in 0..<3 {
            let image = UIGraphicsImageRenderer(size: CGSize(width: 360, height: 300)).image { context in
                colors[index].setFill(); context.fill(CGRect(x: 0, y: 0, width: 360, height: 300))
                UIColor.white.withAlphaComponent(0.75).setFill()
                context.fill(CGRect(x: 45, y: 40, width: 270, height: 190))
                let text = "测试图片 \(index + 1)"
                text.draw(in: CGRect(x: 70, y: 112, width: 250, height: 60), withAttributes: [.font: UIFont.systemFont(ofSize: 28, weight: .medium), .foregroundColor: UIColor.darkGray])
            }
            let url = root.appending(path: "image-\(index + 1).jpg")
            guard let data = image.jpegData(compressionQuality: 0.9) else { throw CocoaError(.fileWriteUnknown) }
            try data.write(to: url, options: .atomic)
            values.append(MediaTile(id: "image\(index + 1)", kind: .image, url: url,
                caption: index == 0 ? "窗框有水渍，雨后再确认\n保留现场细节" : "", relation: index == 0 ? "窗户密封" : ""))
        }
        guard let data = Data(base64Encoded: clip, options: .ignoreUnknownCharacters) else { throw CocoaError(.fileReadCorruptFile) }
        let video = root.appending(path: "fixture.mp4")
        try data.write(to: video, options: .atomic)
        values.append(MediaTile(id: "video", kind: .video, url: video, caption: "开窗过程", relation: "窗户"))
        return values
    }
